let gatewayRequests = materialize(ApiManagementGatewayLogs
| where TimeGenerated {TimeRange}
| where ApiId in~ ('inference-gpt-5-1', 'inference-gpt-4-1-mini')
| project CorrelationId, ApiId, ResponseCode);
let llmPerRequest = ApiManagementGatewayLlmLog
| where TimeGenerated {TimeRange}
| summarize TotalTokens = sum(TotalTokens), LlmRows = count(), RequestMessageChunks = countif(isnotempty(tostring(RequestMessages))), ResponseMessageChunks = countif(isnotempty(tostring(ResponseMessages))) by CorrelationId;
gatewayRequests
| join kind=leftouter llmPerRequest on CorrelationId
| extend Coverage = case(ResponseCode !between (200 .. 299), 'Not expected for non-2xx response', coalesce(TotalTokens, 0) > 0, 'Token telemetry recorded', 'Successful request without token telemetry')
| summarize Requests = count(), TotalTokens = sum(coalesce(TotalTokens, 0)), LlmRows = sum(coalesce(LlmRows, 0)), RequestMessageChunks = sum(coalesce(RequestMessageChunks, 0)), ResponseMessageChunks = sum(coalesce(ResponseMessageChunks, 0)) by ApiId, Coverage
| order by ApiId asc, Coverage asc
| project-rename ['API'] = ApiId, ['Total Tokens'] = TotalTokens, ['LLM Rows'] = LlmRows, ['Request Message Chunks'] = RequestMessageChunks, ['Response Message Chunks'] = ResponseMessageChunks

let gpt51PromptRate = coalesce(todouble('{Gpt51PromptTokenRate}'), 0.0);
let gpt51CompletionRate = coalesce(todouble('{Gpt51CompletionTokenRate}'), 0.0);
let gpt41MiniPromptRate = coalesce(todouble('{Gpt41MiniPromptTokenRate}'), 0.0);
let gpt41MiniCompletionRate = coalesce(todouble('{Gpt41MiniCompletionTokenRate}'), 0.0);
let routes = materialize(ApiManagementGatewayLogs
| where TimeGenerated {TimeRange}
| where ApiId in~ ('inference-gpt-5-1', 'inference-gpt-4-1-mini')
| project CorrelationId, ApiId);
ApiManagementGatewayLlmLog
| where TimeGenerated {TimeRange}
| where TotalTokens > 0 and isnotempty(ModelName)
| project CorrelationId, ModelName, PromptTokens, CompletionTokens
| summarize PromptTokens = sum(PromptTokens), CompletionTokens = sum(CompletionTokens) by CorrelationId, ModelName
| join kind=inner routes on CorrelationId
| extend PromptRate = case(ModelName startswith 'gpt-5.1', gpt51PromptRate, ModelName startswith 'gpt-4.1-mini', gpt41MiniPromptRate, 0.0), CompletionRate = case(ModelName startswith 'gpt-5.1', gpt51CompletionRate, ModelName startswith 'gpt-4.1-mini', gpt41MiniCompletionRate, 0.0)
| extend TotalCost = round((PromptTokens * PromptRate + CompletionTokens * CompletionRate) / 1000.0, 6)
| summarize ['Total Cost ($)'] = sum(TotalCost) by ModelName
| project ['Model'] = ModelName, ['Total Cost ($)']
| order by ['Total Cost ($)'] desc
